class InstallManager{constructor(){this.deferredPrompt=null,this.isInstalled=!1,this.promptShown=!1}init(){window.addEventListener("beforeinstallprompt",t=>{t.preventDefault(),this.deferredPrompt=t,this.showInstallButton(),console.log("beforeinstallprompt event captured")}),window.addEventListener("appinstalled",t=>{console.log("PWA was installed"),this.trackInstallation("accepted"),this.isInstalled=!0,this.hideInstallButton(),this.deferredPrompt=null})}showInstallButton(){const t=document.getElementById("install-button");t&&(t.style.display="block",console.log("Install button shown"))}hideInstallButton(){const t=document.getElementById("install-button");t&&(t.style.display="none",console.log("Install button hidden"))}async promptInstall(){if(!this.deferredPrompt)return void console.log("No deferred prompt available");this.promptShown=!0,this.deferredPrompt.prompt();const{outcome:t}=await this.deferredPrompt.userChoice;console.log(`User response to install prompt: ${t}`),this.trackInstallation(t),this.deferredPrompt=null,"accepted"===t&&this.hideInstallButton()}trackInstallation(t){console.log(`Installation outcome: ${t}`);const e=(new Date).toISOString();console.log(`[${e}] PWA Installation ${t}`)}}"undefined"!=typeof module&&module.exports&&(module.exports=InstallManager);